// Locale parity gate (`website / locale parity`): the site is maintained in English and German
// together, so every page under src/content/docs/ must exist at the root (English) and under de/
// (German) with the same slug, and every screenshot in four variants (en|de x light|dark).
// No allow-list: the API reference is generated by starlight-openapi, not a content file.
import { existsSync, readdirSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const PAGE = /\.(md|mdx)$/;
const SHOT = /^(?<shot>.+)\.(?<lang>en|de)\.(?<theme>light|dark)\.webp$/;
const VARIANTS = ["en.light", "en.dark", "de.light", "de.dark"];

function walk(dir) {
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(path));
    else out.push(path);
  }
  return out;
}

/** Slugs are paths under the docs root without extension; `.md` and `.mdx` are equal. */
export function findParityGaps(root) {
  const en = new Set();
  const de = new Set();
  for (const file of walk(root)) {
    if (!PAGE.test(file)) continue;
    const slug = relative(root, file).split(sep).join("/").replace(PAGE, "");
    if (slug.startsWith("de/")) de.add(slug.slice(3));
    else en.add(slug);
  }
  const missingDe = [...en].filter((slug) => !de.has(slug)).sort();
  const missingEn = [...de].filter((slug) => !en.has(slug)).sort();
  return { missingDe, missingEn };
}

/** A shot is complete with all four variants; returns the missing file names. */
export function findScreenshotGaps(dir) {
  if (!existsSync(dir)) return [];
  const seen = new Map();
  for (const name of readdirSync(dir)) {
    const match = SHOT.exec(name);
    if (!match) continue;
    const { shot, lang, theme } = match.groups;
    if (!seen.has(shot)) seen.set(shot, new Set());
    seen.get(shot).add(`${lang}.${theme}`);
  }
  const missing = [];
  for (const [shot, have] of [...seen].sort(([a], [b]) => a.localeCompare(b))) {
    for (const variant of VARIANTS) {
      if (!have.has(variant)) missing.push(`${shot}.${variant}.webp`);
    }
  }
  return missing;
}

function main() {
  const site = join(dirname(fileURLToPath(import.meta.url)), "..");
  const { missingDe, missingEn } = findParityGaps(join(site, "src", "content", "docs"));
  const shots = findScreenshotGaps(join(site, "src", "assets", "screens"));
  for (const slug of missingDe) console.log(`missing de: ${slug}`);
  for (const slug of missingEn) console.log(`missing en: ${slug}`);
  for (const file of shots) console.log(`missing screenshot: ${file}`);
  if (missingDe.length || missingEn.length || shots.length) {
    console.log("Every page needs an English and a German version (see CONTRIBUTING.md, Website).");
    process.exit(1);
  }
  console.log("locale parity: every page exists in en and de");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
